// Pull the JSON object out of the model's reply and return it as { config }.
const text = $json.choices?.[0]?.message?.content || '';
const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
const body = fenced ? fenced[1] : text;
const s = body.indexOf('{');
const e = body.lastIndexOf('}');
let config = null;
if (s >= 0 && e > s) { try { config = JSON.parse(body.slice(s, e + 1)); } catch (err) {} }
return [{ json: { config } }];
